<script setup>
import { ref, reactive, computed, watch, onMounted } from "vue";
import { Moon, Globe, Sun, MonitorCheck, MapPin, Send } from "lucide-vue-next";

/* ============ DROPDOWN STATE ============ */
const isShowMode = ref(false);
const isShow = ref(false);
const activeMode = ref("device");
const active = ref("uz"); // uz | ru | en

const languages = [
  { code: "uz", label: "O'zbekcha" },
  { code: "ru", label: "Русский" },
  { code: "en", label: "English" },
];

const techStack = [
  "Vue 3",
  "React",
  "PHP",
  "MySQL",
  "Java",
  "Bootstrap",
  "Git",
  "Tailwind CSS",
];

/* ============ THEME LOGIC ============ */
function applyMode(mode) {
  const isDark =
    mode === "dark" ||
    (mode === "device" &&
      window.matchMedia("(prefers-color-scheme: dark)").matches);
  document.documentElement.classList.toggle("dark", isDark);
}

function selectMode(mode) {
  activeMode.value = mode;
  isShowMode.value = false;
  try {
    localStorage.setItem("theme", mode);
  } catch (e) {}
}

function select(langCode) {
  active.value = langCode;
  isShow.value = false;
  try {
    localStorage.setItem("lang", langCode);
  } catch (e) {}
}

onMounted(() => {
  let savedMode = "device";
  let savedLang = "uz";
  try {
    savedMode = localStorage.getItem("theme") || "device";
    savedLang = localStorage.getItem("lang") || "uz";
  } catch (e) {}

  // Himoya: eski/noto'g'ri qiymat bo'lsa standart holatga qaytaramiz
  if (!["light", "dark", "device"].includes(savedMode)) savedMode = "device";
  if (!translations[savedLang]) savedLang = "uz";

  activeMode.value = savedMode;
  active.value = savedLang;
  applyMode(savedMode);

  window
    .matchMedia("(prefers-color-scheme: dark)")
    .addEventListener("change", () => {
      if (activeMode.value === "device") applyMode("device");
    });
});

watch(activeMode, (val) => applyMode(val));

/* ============ NAV ============ */
const navLinks = [
  { id: 1, key: "about", section: "about" },
  { id: 2, key: "experience", section: "experience" },
  { id: 3, key: "projects", section: "projects" },
  { id: 4, key: "articles", section: "articles" },
  { id: 5, key: "contact", section: "contact" },
];

function scrollToSection(id) {
  const el = document.getElementById(id);
  if (el) {
    const yOffset = -100;
    const y = el.getBoundingClientRect().top + window.pageYOffset + yOffset;
    window.scrollTo({ top: y, behavior: "smooth" });
  }
}

